import{_ as t,o as a,c as i,a0 as n}from"./chunks/framework.bcCluOOn.js";const m=JSON.parse('{"title":"Compiler & Target Generators","description":"","frontmatter":{},"headers":[],"relativePath":"specification/compiler.md","filePath":"specification/compiler.md"}'),r={name:"specification/compiler.md"};function o(c,e,s,l,d,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="compiler-target-generators" tabindex="-1">Compiler &amp; Target Generators <a class="header-anchor" href="#compiler-target-generators" aria-label="Permalink to &quot;Compiler &amp; Target Generators&quot;">​</a></h1><p>Unlike traditional languages that compile down to machine code or a single virtual machine bytecode, AAYU employs a multi-stage, retargetable compilation pipeline. The compiler doesn&#39;t just evaluate syntax; it evaluates <em>intent</em> and <em>architecture</em>.</p><h2 id="the-compilation-pipeline" tabindex="-1">The Compilation Pipeline <a class="header-anchor" href="#the-compilation-pipeline" aria-label="Permalink to &quot;The Compilation Pipeline&quot;">​</a></h2><p>The AAYU pipeline consists of four distinct phases:</p><h3 id="_1-lexing-and-parsing-frontend" tabindex="-1">1. Lexing and Parsing (Frontend) <a class="header-anchor" href="#_1-lexing-and-parsing-frontend" aria-label="Permalink to &quot;1. Lexing and Parsing (Frontend)&quot;">​</a></h3><p>The AAYU parser reads <code>.aayu</code> source code and constructs an Abstract Syntax Tree (AST). It performs syntactic validation (e.g., ensuring blocks are closed with <code>end.</code>).</p><h3 id="_2-intermediate-representation-aayu-ir" tabindex="-1">2. Intermediate Representation (AAYU IR) <a class="header-anchor" href="#_2-intermediate-representation-aayu-ir" aria-label="Permalink to &quot;2. Intermediate Representation (AAYU IR)&quot;">​</a></h3><p>The AST is transformed into the <strong>AAYU IR</strong>, a language-agnostic JSON structure. This IR represents the pure architectural intent of the software—entities, routes, workflows, and RBAC rules—stripped of syntactic sugar.</p><p><a href="/INTENT-TO-SILICON/specification/ir.html">Read the full AAYU IR Specification →</a></p><h3 id="_3-target-selection-engine" tabindex="-1">3. Target Selection Engine <a class="header-anchor" href="#_3-target-selection-engine" aria-label="Permalink to &quot;3. Target Selection Engine&quot;">​</a></h3><p>This is a unique layer in the AAYU architecture. A rules-engine analyzes the AAYU IR and determines the optimal technology stack required to execute the intent.</p><p>For example, if the IR contains a heavy AI/ML workload, the engine might select a Python/FastAPI target. If it defines a complex UI with <code>dashboard</code> and <code>sidebar</code> components, it might select a React target for the frontend.</p><h3 id="_4-target-generation-backend" tabindex="-1">4. Target Generation (Backend) <a class="header-anchor" href="#_4-target-generation-backend" aria-label="Permalink to &quot;4. Target Generation (Backend)&quot;">​</a></h3><p>Based on the selection, specific generators emit the final code.</p><ul><li>A backend generator might emit a raw SQLite schema and FastAPI Python code.</li><li>A frontend generator might emit a Next.js application.</li></ul><p>Alternatively, the compiler can bypass explicit code generation and compile the IR into AAYU Bytecode (<code>.ayc</code>) to be executed directly by the <strong>AAYU Native Runtime</strong>.</p>',16)])])}const g=t(r,[["render",o]]);export{m as __pageData,g as default};
